import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r

def build(arr):
    if not arr or arr[0] == 'n':
        return None
    root = T(int(arr[0]))
    q = deque([root])
    i = 1
    while q and i < len(arr):
        n = q.popleft()
        if i < len(arr) and arr[i] != 'n':
            n.l = T(int(arr[i])); q.append(n.l)
        i += 1
        if i < len(arr) and arr[i] != 'n':
            n.r = T(int(arr[i])); q.append(n.r)
        i += 1
    return root

def path_sum_brute(root, target):
    res = []
    def dfs(node, s, path):
        if not node: return
        path.append(node.v)
        s += node.v
        if not node.l and not node.r and s == target:
            res.append(path[:])
        else:
            dfs(node.l, s, path)
            dfs(node.r, s, path)
        path.pop()
    dfs(root, 0, [])
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    arr = data[1:1 + n]
    target = int(data[1 + n])
    root = build(arr)
    res = path_sum_brute(root, target)
    for p in res:
        print(' '.join(map(str, p)))

