def path_sum_opt(root, target):
    if not root: return []
    res = []
    stack = [(root, [root.v], root.v)]
    while stack:
        n, path, s = stack.pop()
        if not n.l and not n.r and s == target:
            res.append(path)
            continue
        if n.r:
            stack.append((n.r, path + [n.r.v], s + n.r.v))
        if n.l:
            stack.append((n.l, path + [n.l.v], s + n.l.v))
    return res

